import{_ as a,c as e,o as n,ag as t}from"./chunks/framework.Bee44SUS.js";const b=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"src/Linux/Linux/VMware Fusion 中Ubuntu虚拟机磁盘空间释放.md","filePath":"src/Linux/Linux/VMware Fusion 中Ubuntu虚拟机磁盘空间释放.md","lastUpdated":1788418940000}'),p={name:"src/Linux/Linux/VMware Fusion 中Ubuntu虚拟机磁盘空间释放.md"};function i(o,s,l,u,d,c){return n(),e("div",null,[...s[0]||(s[0]=[t(`<h2 id="vmware-fusion-中ubuntu虚拟机磁盘空间释放" tabindex="-1">VMware Fusion 中Ubuntu虚拟机磁盘空间释放 <a class="header-anchor" href="#vmware-fusion-中ubuntu虚拟机磁盘空间释放" aria-label="Permalink to &quot;VMware Fusion 中Ubuntu虚拟机磁盘空间释放&quot;">​</a></h2><p>Ubuntu虚拟机采用虚拟磁盘拆分成多个文件管理方式时，释放Ubuntu虚拟机中未使用的空闲空间，以缩小宿主机(当前是在macOS上)中<code>.vmwarevm</code>虚拟机文件的大小。这里要释放虚拟机中未使用的空闲空间。 <br> 比如：当前Ubuntu虚拟机中使用了20GB,这时候查看macOS上的<code>.vmwarevm</code>文件大小也是20GB左右，这是就不需要释放Ubuntu虚拟机的空闲磁盘。但是现在在Ubuntu中下载了一个20GB的文件，此时在Ubuntu中通过<code>df -h</code>或者<code>df -h /</code>查看时就会看到Ubuntu的磁盘使用量在40GB左右，然后再查看macOS上的<code>.vmwarevm</code>文件也是40GB左右。 <br> 注意：这个时候再Ubuntu中将这个20GB的文件使用rm或者其他方式删除后，再查看Ubuntu中的磁盘的使用量就会回到20GB，<strong>然而这是后再查看macOS上的<code>.vmwarevm</code>文件就会发现它的大小还是在40GB左右，这时候就需要手动去释放这个Ubuntu虚拟机的空闲磁盘(就释放掉垃圾数据的空间)。</strong> <br> 这时想到的方式是直接使用VMware Fusion虚拟的设置中的磁盘垃圾回收操作，就会发现设置中垃圾清理操作是无法清理的，这时就需要使用VMware Fusion中的<strong>vmware-vdiskmanager</strong>工具并使用**-k**命令来清理空间。使用这个工具的前提是需要再Ubuntu中将空闲空间使用逻辑0写满然后再使用这个工具释放空间就能达到清理Ubuntu虚拟机在macOS上占用的大小。</p><h2 id="相关命令详解" tabindex="-1">相关命令详解： <a class="header-anchor" href="#相关命令详解" aria-label="Permalink to &quot;相关命令详解：&quot;">​</a></h2><p>1 查看磁盘使用详情：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#ubuntu</span></span>
<span class="line"><span>df -h </span></span>
<span class="line"><span>df -h /</span></span></code></pre></div><p>2 创建一个逻辑大小为1GB，并且内容全部是0的文件zero.fill的文件。bs=64M表示每块大小64M，总计16块空1GB。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#ubuntu</span></span>
<span class="line"><span>sudo dd if=/dev/zero of=/zero.fill bs=64M count=16 status=progress</span></span></code></pre></div><p>3 创建一个内容完全填充为0的zero.fill文件，文件的逻辑大小为剩余的所有空闲空间大小，即该操作会将剩余磁盘全部写完。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#ubuntu</span></span>
<span class="line"><span>sudo dd if=/dev/zero of=/zero.fill bs=1M status=progress</span></span></code></pre></div><p>4 删除zero.fill逻辑文件</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#ubuntu</span></span>
<span class="line"><span>sudo rm -f /zero.fill</span></span></code></pre></div><p>5 同步操作</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#ubuntu</span></span>
<span class="line"><span>sync</span></span></code></pre></div><p>6 在macOS上使用du查看虚拟机在macOS上占用的磁盘大小。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#macos</span></span>
<span class="line"><span>du -sh &quot;Ubuntu-Desktop.vmwarevm&quot;</span></span></code></pre></div><p>7 使用vmware-vdiskmanager工具释放虚拟机中填充0的数据以达到释放虚拟的的空间效果。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;/Volumes/ExData/Applications/VM/VMware Fusion.app/Contents/Library/vmware-vdiskmanager&quot; \\</span></span>
<span class="line"><span>-k &quot;Ubuntu-Desktop.vmwarevm/虚拟磁盘.vmdk&quot;</span></span></code></pre></div><p>Ubuntu-Desktop.vmwarevm：具体的虚拟机文件名称，由你的虚拟机确定。 <br> 虚拟磁盘.vmdk：虚拟磁盘的文件名，由你的虚拟机确定，注意不是形如<code>虚拟磁盘-s001.vmdk</code>的拆分文件。</p><p>8 使用vmware-vdiskmanager工具进行磁盘碎片整理操作。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#macos</span></span>
<span class="line"><span>&quot;/Volumes/ExData/Applications/VM/VMware Fusion.app/Contents/Library/vmware-vdiskmanager&quot; \\</span></span>
<span class="line"><span>-d &quot;Ubuntu-Desktop.vmwarevm/虚拟磁盘.vmdk&quot;</span></span></code></pre></div><h2 id="具体的ubuntu磁盘空间释放的步骤" tabindex="-1">具体的Ubuntu磁盘空间释放的步骤： <a class="header-anchor" href="#具体的ubuntu磁盘空间释放的步骤" aria-label="Permalink to &quot;具体的Ubuntu磁盘空间释放的步骤：&quot;">​</a></h2><p><strong>第一步</strong>：先在Ubuntu中使用df命令查看磁盘使用详情：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>df -h </span></span>
<span class="line"><span>df -h /</span></span></code></pre></div><p><strong>第二步</strong>：再在Ubuntu中创建填充0的zero.fill逻辑文件：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo dd if=/dev/zero of=/zero.fill bs=64M count=16 status=progress</span></span></code></pre></div><p>这只是创建逻辑大小为<strong>1GB</strong>的文件。这时候可以通过<code>du -sh Ubuntu-Desktop.vmwarevm</code> 查看macOS上虚拟机的磁盘占用情况。 <br> 这时候可以尝试在Ubuntu上创建5G,10G 20G的zero.fill文件然后再同时查看<code>du -sh Ubuntu-Desktop.vmwarevm</code>的文件是否会巨增？ <br> 这样可以安全的尝试防止*.vmwarevm*文件大小巨增。 <br> 如果没有就可以在Ubuntu中将剩余的空间全部进行zero.fill操作，写满Ubuntu剩余空间：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo dd if=/dev/zero of=/zero.fill bs=1M status=progress</span></span></code></pre></div><p><strong>注意</strong>: 当前进行zero操作并不会让macOS上的<code>.vmwarevm</code>文件大小巨增，不过为了安全还是建议先一步一步扩大zero.fill文件的大小。 <br> 如果<code>.vmwarevm</code>文件没有明显的巨增，就可以直接使用将剩余空间写满的方式创建zero.fill文件。</p><p><strong>第三步</strong>：再次查看Ubuntu磁盘空间使用详情：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>df -h /</span></span></code></pre></div><p><strong>第四步</strong>：执行同步操作并删除zero.fill文件:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sync</span></span>
<span class="line"><span>sudo rm -f /zero.fill</span></span>
<span class="line"><span>sync</span></span></code></pre></div><p><strong>第五步</strong>：再次查看Ubuntu的磁盘使用情况：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>df -h /</span></span></code></pre></div><p><strong>第六步</strong>：Ubuntu关机操作</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo poweroff</span></span></code></pre></div><p><strong>第七步</strong>：先在macOS上查看<code>.vmwarevm</code>虚拟机文件大小：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>du -sh &quot;Ubuntu-Desktop.vmwarevm&quot;</span></span></code></pre></div><p><strong>第八步</strong>：再在macOS上执行磁盘空间清理操作:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;/Volumes/ExData/Applications/VM/VMware Fusion.app/Contents/Library/vmware-vdiskmanager&quot; \\</span></span>
<span class="line"><span>-k &quot;Ubuntu-Desktop.vmwarevm/虚拟磁盘.vmdk&quot;</span></span></code></pre></div><p><strong>第九步</strong>：再次查看<code>.vmwarevm</code>虚拟机文件大小</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>du -sh &quot;Ubuntu-Desktop.vmwarevm&quot;</span></span></code></pre></div><p>比较这两次的du操作，看他们之间缩小的大小是否达到目标。比如：<code>.vmwarevm</code>文件的大小只比Ubuntu中磁盘使用大小大一点， <br> 比如几个G之类的则说明此时磁盘清理达到了目标。如果相差很大则重复整个Ubuntu磁盘清理操作，如果依旧不理想则继续重复即可。</p>`,43)])])}const h=a(p,[["render",i]]);export{b as __pageData,h as default};
